'use client'
 
import { useCallback, useEffect, useRef, useState } from 'react'
import type { Batch, InferenceParams, Run } from './types'
import { makeBatch, streamInference } from './inference-engine'

export function useInvestigations() {
  const [runs, setRuns] = useState<Run[]>([])
  const [activeRunId, setActiveRunId] = useState<string | null>(null)
  const cancelMap = useRef<Map<string, () => void>>(new Map())

  const startRun = useCallback((params: InferenceParams) => {
    const id = `run-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`
    const expectedBatches = 2 //4 + Math.floor(Math.random() * 3)
    const run: Run = {
      id,
      params,
      createdAt: Date.now(),
      status: 'streaming',
      batches: [],
      expectedBatches,
    }
    setRuns((prev) => [run, ...prev])
    setActiveRunId(id)







    const ws = new WebSocket("ws://localhost:8000/ws")

    ws.onopen = () => {
      console.log("WebSocket connected")
    }

    ws.onclose = (event) => {
      console.log("WebSocket closed")
      console.log("Code:", event.code)
      console.log("Reason:", event.reason)
    }

    ws.onerror = (err) => {
      console.error("WebSocket error:", err)
    }

    ws.onopen = () => {
      console.log("WebSocket opened")
      ws.send(
        JSON.stringify({
          type: "execute",
          params,
        })
      )
    }

    ws.onmessage = (event) => {
      const msg = JSON.parse(event.data)

      console.log("Received websocket message:", msg)

      alert(msg.message)
    }







    /*
    const cancel = streamInference(
      expectedBatches,
      (batch: Batch) => {
        setRuns((prev) =>
          prev.map((r) =>
            r.id === id ? { ...r, batches: [...r.batches, batch] } : r,
          ),
        )
      },
      () => {
        setRuns((prev) =>
          prev.map((r) => (r.id === id ? { ...r, status: 'complete' } : r)),
        )
        cancelMap.current.delete(id)
      },
    )
    cancelMap.current.set(id, cancel)
 */ 
    return id
  }, [])

  const selectRun = useCallback((id: string | null) => {
    setActiveRunId(id)
  }, [])

  // cleanup on unmount
  useEffect(() => {
    const map = cancelMap.current
    return () => {
      map.forEach((cancel) => cancel())
      map.clear()
    }
  }, [])

  const activeRun = runs.find((r) => r.id === activeRunId) ?? null

  return { runs, activeRun, activeRunId, startRun, selectRun }
}

// re-export for convenience
export { makeBatch }
