import type { Batch, SegmentationTile, SegmentClass } from './types'

const SATELLITE_IMAGES = [
  '/satellite-1.png',
  '/satellite-2.png',
  '/satellite-3.png',
  '/satellite-4.png',
]

const CLASS_PALETTE: { label: string; color: string }[] = [
  { label: 'Dense Forest', color: 'oklch(0.5 0.1 150)' },
  { label: 'Cropland', color: 'oklch(0.72 0.11 110)' },
  { label: 'Grassland', color: 'oklch(0.78 0.1 130)' },
  { label: 'Water', color: 'oklch(0.62 0.08 220)' },
  { label: 'Wetland', color: 'oklch(0.58 0.07 180)' },
  { label: 'Bare Soil', color: 'oklch(0.65 0.08 70)' },
  { label: 'Urban', color: 'oklch(0.55 0.02 60)' },
]

function randomBetween(min: number, max: number) {
  return Math.random() * (max - min) + min
}

function makeClasses(): SegmentClass[] {
  const count = 3 + Math.floor(Math.random() * 3)
  const picked = [...CLASS_PALETTE]
    .sort(() => Math.random() - 0.5)
    .slice(0, count)
  const raw = picked.map(() => randomBetween(0.1, 1))
  const total = raw.reduce((a, b) => a + b, 0)
  return picked
    .map((p, i) => ({
      id: `${p.label}-${i}`,
      label: p.label,
      color: p.color,
      coverage: Math.round((raw[i] / total) * 1000) / 10,
    }))
    .sort((a, b) => b.coverage - a.coverage)
}

function makeTile(seed: number): SegmentationTile {
  return {
    id: `tile-${seed}-${Math.random().toString(36).slice(2, 7)}`,
    image: SATELLITE_IMAGES[seed % SATELLITE_IMAGES.length],
    lat: Math.round(randomBetween(-12, 48) * 10000) / 10000,
    lng: Math.round(randomBetween(-78, 24) * 10000) / 10000,
    confidence: Math.round(randomBetween(78, 99) * 10) / 10,
    classes: makeClasses(),
  }
}

export function makeBatch(index: number): Batch {
  const tiles = Array.from({ length: 1 }, (_, i) =>
    makeTile(index * 4 + i),
  )
  const meanConfidence =
    Math.round(
      (tiles.reduce((a, t) => a + t.confidence, 0) / tiles.length) * 10,
    ) / 10

  // dominant class across the batch
  const tally = new Map<string, number>()
  tiles.forEach((t) =>
    t.classes.forEach((c) =>
      tally.set(c.label, (tally.get(c.label) ?? 0) + c.coverage),
    ),
  )
  const dominantClass =
    [...tally.entries()].sort((a, b) => b[1] - a[1])[0]?.[0] ?? 'Unknown'

  return {
    id: `batch-${index}-${Math.random().toString(36).slice(2, 7)}`,
    index,
    label: `Observation ${String(index + 1).padStart(2, '0')}`,
    receivedAt: Date.now(),
    tiles,
    meanConfidence,
    dominantClass,
  }
}

/**
 * Simulates a backend that streams segmentation results in batches.
 * Calls onBatch for each batch with a randomized delay, then onComplete.
 * Returns a cancel function.
 */
export function streamInference(
  expectedBatches: number,
  onBatch: (batch: Batch) => void,
  onComplete: () => void,
): () => void {
  let cancelled = false
  let index = 0
  let timer: ReturnType<typeof setTimeout>

  const tick = () => {
    if (cancelled) return
    if (index >= expectedBatches) {
      onComplete()
      return
    }
    onBatch(makeBatch(index))
    index += 1
    timer = setTimeout(tick, randomBetween(1400, 2800))
  }

  // initial delay before first batch
  timer = setTimeout(tick, 900)

  return () => {
    cancelled = true
    clearTimeout(timer)
  }
}

